@patch
def tree(self:Path, 
    file_type:str=None,
    file_exts:list=None,
    exclude:list=None,
    hidden:bool=False,
    max_level:int=None,
    on_file:Callable=None,
    on_dir:Callable=None,
) -> TreeNode:
    "Return a TreeNode rooted at path with optional inclusions/exclusions and leaf/node transforms"
    import mimetypes
    extns = L(file_exts)
    if file_type: extns += L(k for k,v in mimetypes.types_map.items() if v.startswith(file_type+'/'))
    has_extns = len(extns)==0
    exclude = set(exclude or [])
    def _node(p, children): return on_dir(p, children) if on_dir else TreeNode(p, children)
    def _kids(p, lvl=0):
        if max_level is not None and lvl >= max_level: return []
        children = []
        for o in sorted(p.iterdir(), key=_gett):
            if o.name in exclude or (not hidden and o.name.startswith('.')): continue
            if o.is_dir():
                kids = None if max_level is not None and lvl+1 >= max_level else _kids(o, lvl+1)
                children.append(_node(o, kids or []))
            elif has_extns or o.suffix in extns: children.append(on_file(o) if on_file else o)
        return children
    return _node(self, _kids(self))

