def _indent(indent=2):
    _pre = lambda p, v, ctx: print(' '*indent*ctx['depth'] + str(next(iter(v))) + ':')
    _leaf = lambda p, v, ctx: print(' '*indent*ctx['depth'] + str(v))
    # for k in tr: print(f"{k}:"); transform({k: tr[k]}, on_leaf=_leaf, on_node_pre=_pre)
    return dict(on_node_pre=_pre, on_leaf=_leaf)

# %% ../nbs/01_tree.ipynb #a1262477
def _as_node(o): return from_dict(o) if isinstance(o, Mapping) else o

def _print_indent(tr, indent):
    def _pre(ctx, p, v, c): print(' '*indent*c['depth'] + str(v.key) + ':')
    def _leaf(ctx, p, v, c): print(' '*indent*c['depth'] + str(v))
    visit(_as_node(tr), on_node_pre=_pre, on_leaf=_leaf)

def _print_tree(tr, color=True):
    _d,_r,_g = ('\033[34m','\033[0m','\033[38;5;7m') if color else ('','','')
    last = {}
    def _pfx(c): return ''.join('    ' if last.get(i) else '│   ' for i in range(1, c['depth'])) + ('└── ' if c['is_last'] else '├── ')*bool(c['depth'])
    def _pre(ctx, p, v, c): last[c['depth']] = c['is_last']; print(_g + _pfx(c) + _r + _d + str(v.key) + _r)
    def _leaf(ctx, p, v, c): print(_g + _pfx(c) + _r + str(v))
    visit(_as_node(tr), on_node_pre=_pre, on_leaf=_leaf)

def pprint(tr, style='indent', indent=2, color=True):
    "Pretty print a tree in 'indent' or 'tree' style"
    if style == 'tree': _print_tree(tr, color)
    else: _print_indent(tr, indent)

