class FileMeta(Path):
    "Path with attached metadata dict"
    def __new__(cls, *args, **kwargs): return super().__new__(cls, *args)
    def __init__(self, *args, **kwargs):
        super().__init__(*args)
        self.meta = AttrDict(kwargs)

