class TreeEvt:
    "Traversal event"
    def __init__(self, kind, p, v, ctx): self.kind,self.p,self.v,self.ctx = kind,p,v,ctx
    def __iter__(self): return iter((self.p,self.v,self.ctx))
    def __repr__(self): return f"TreeEvt({self.kind!r}, {self.p!r}, {self.v!r}, {self.ctx!r})"

class TreeWalk(HasCallbacks):
    "Stack-based depth-first tree walker with callbacks"
    cbs_names = ('before_walk','after_walk','on_root_pre','on_root_post','on_meta','on_node_pre','on_node_post','on_leaf')

    def __init__(self, m:TreeNode, cbs=()):
        self.m = m
        super().__init__(cbs=cbs)

    def _evt(self, kind, p, v, depth, idx, n_sibs):
        return TreeEvt(kind, p, v, dict(depth=depth, idx=idx, n_sibs=n_sibs, is_last=idx==n_sibs-1))

    def _callback(self, e):
        if e.kind == 'on_node_pre' and not e.p: self.callback('on_root_pre', e.p, e.v, e.ctx)
        if e.kind == 'on_node_pre': self.callback('on_meta', e.p, e.v, e.ctx)
        self.callback(e.kind, e.p, e.v, e.ctx)
        if e.kind == 'on_node_post' and not e.p: self.callback('on_root_post', e.p, e.v, e.ctx)

    def __iter__(self):
        self.callback('before_walk')
        stack = [self._evt('on_node_pre', (), self.m, 0, 0, 1)]
        while stack:
            e = stack.pop()
            self._callback(e)
            yield e
            if e.kind == 'on_node_pre':
                n = len(e.v.children)
                stack.append(self._evt('on_node_post', e.p, e.v, e.ctx['depth'], e.ctx['idx'], e.ctx['n_sibs']))
                for i,c in reversed(list(enumerate(e.v.children))):
                    p = e.p + (c.key if is_tree(c) else i,)
                    stack.append(self._evt('on_node_pre' if is_tree(c) else 'on_leaf', p, c, e.ctx['depth']+1, i, n))
        self.callback('after_walk')

# %% ../nbs/01_tree.ipynb #4988b4e3
def visit(m: TreeNode, on_leaf: Callable=None, on_node_pre: Callable=None, on_node_post: Callable=None, on_root_pre: Callable=None, on_root_post: Callable=None, on_meta: Callable=None):
    "Depth-first walk calling callbacks for side effects"
    cbs = [CBs(**{k:v for k,v in dict(on_leaf=on_leaf, on_node_pre=on_node_pre, on_node_post=on_node_post, on_root_pre=on_root_pre, on_root_post=on_root_post, on_meta=on_meta).items() if v})]
    for _ in TreeWalk(m, cbs=cbs): pass

# %% ../nbs/01_tree.ipynb #ae848b21
def search(m: TreeNode, pred: Callable):
    "Find all (path, leaf) pairs where leaf satisfies pred"
    return [(e.p, e.v) for e in TreeWalk(m) if e.kind=='on_leaf' and pred(e.v)]

def search_path(m: TreeNode, pred: Callable):
    "Find all (path, leaf) pairs where path satisfies pred"
    return [(e.p, e.v) for e in TreeWalk(m) if e.kind=='on_leaf' and pred(e.p)]

# %% ../nbs/01_tree.ipynb #0d4646e6
def transform(m: TreeNode, on_leaf: Callable=None, on_node: Callable=None) -> TreeNode:
    "Depth-first structural transform, returning new TreeNode"
    if not is_tree(m): return on_leaf((), m) if on_leaf else m
    stack, cur = [], []
    for e in TreeWalk(m):
        if e.kind=='on_node_pre': stack.append(cur); cur = []
        elif e.kind=='on_leaf':
            r = on_leaf(e.p, e.v) if on_leaf else e.v
            if r is not _SKIP: cur.append(r)
        elif e.kind=='on_node_post':
            children = cur; cur = stack.pop()
            r = on_node(e.p, TreeNode(e.v.key, children, **e.v.meta)) if on_node else None
            if r is not _SKIP: cur.append(TreeNode(e.v.key, children, **e.v.meta) if r is None else r)
    return cur[0] if cur else TreeNode(m.key)

# %% ../nbs/01_tree.ipynb #4a34322f
def filter_leaves(m: TreeNode, pred: Callable) -> TreeNode:
    "Keep only leaves satisfying pred, empty branches remain"
    return transform(m, on_leaf=lambda p,v: v if pred(v) else _SKIP)

def prune(m: TreeNode, pred: Callable) -> TreeNode:
    "Keep only leaves satisfying pred, removing empty branches"
    return transform(m, on_leaf=lambda p,v: v if pred(v) else _SKIP, on_node=lambda p,v: v if v.children else _SKIP)

def map_leaves(m: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every leaf"
    return transform(m, on_leaf=lambda p,v: f(v))

def map_nodes(m: TreeNode, f: Callable) -> TreeNode:
    "Return new tree with f applied to every node"
    return transform(m, on_node=lambda p,v: f(v))

def reduce_leaves(m: TreeNode, f: Callable, init=None):
    "Reduce all leaves left-to-right with f(acc, leaf)"
    acc = init
    for e in TreeWalk(m):
        if e.kind=='on_leaf': acc = f(acc, e.v)
    return acc

# %% ../nbs/01_tree.ipynb #b87901bf
def _open_set(tr, opened, nm=str):
    res = set()
    def _want(e):
        if opened is None: return False
        if callable(opened): return opened(e.v.key, e.v)
        return e.v.key in opened or nm(e.v.key) in opened or e.p in opened
    for e in TreeWalk(_as_node(tr)):
        if e.kind=='on_node_pre' and _want(e):
            for i in range(len(e.p)+1): res.add(e.p[:i])
    return res

