def show_tree(tr, trf=None, open_parent=False, opened=None, **kwargs):
    "Show tree as HTML"
    trf = trf or details_tree_transform
    if open_parent: opened = _open_set(tr, opened, kwargs.get('nm', str))
    show(transform(_as_node(tr), **trf(opened=opened, **kwargs)))

# %% ../nbs/01_tree.ipynb #d9d97e45
def details_tree_transform(nm=str, data_nm=None, opened=None, root_key='root', node_attrs=None, leaf_attrs=None, coll_attrs=None):
    "Transform a TreeNode to details/summary/ul/li HTML"
    data_nm = data_nm or nm
    def _attrs(f, p, v): return f(p, v) if f else {}
    def _open(p, v, is_root):
        if is_root: return True
        if opened is None: return False
        if callable(opened): return opened(v.key, v)
        return v.key in opened or nm(v.key) in opened or p in opened
    def _leaf(p, v): return Li(nm(v), data_it=True, **_attrs(leaf_attrs, p, v))
    def _node(p, v):
        is_root = not p
        d = Details(Summary(nm(v.key)), Ul(*v.children, data_coll_name=data_nm(v.key), **_attrs(coll_attrs, p, v)), open=_open(p, v, is_root), **_attrs(node_attrs, p, v))
        if is_root: return Div(*v.children, cls='tree') if v.key==root_key else Div(d, cls='tree')
        return Li(d, data_it=True)
    return dict(on_leaf=_leaf, on_node=_node)

