def meta_attrs(*names):
    "Create attrs callback from TreeNode meta"
    return lambda p,v: {f"data_{n}": True for n in names if v.meta.get(n)}

# %% ../nbs/01_tree.ipynb #8d99aa23
def opened_from_meta(name='open'):
    "Create opened callback from TreeNode meta"
    return lambda k,v: bool(v.meta.get(name))

