@patch
def __getitem__(self:TreeNode, k):
    if isinstance(k, tuple): return val_atpath(self, *k)
    if isinstance(k, int): return self.children[k]
    for c in self.children:
        if is_tree(c) and c.key == k: return c
    raise KeyError(k)

# %% ../nbs/01_tree.ipynb #f387d308
def dlink(dname, text=None, msg_id=None):
    "Return Solveit dialog link with custom text"
    nm = dname[1:] if str(dname).startswith('/') else str(dname)
    href = f"/dialog_?name={quote(nm)}" + (f"#{msg_id}" if msg_id else "")
    return A(text or Path(nm).name, href=href, target='_blank')

# %% ../nbs/01_tree.ipynb #a415e926
def _dlg_nm(p):
    if isinstance(p, Path) and p.suffix=='.ipynb':
        d = '/' + str(p.resolve().with_suffix('').relative_to(Path('/app/data')))
        return dlink(d, p.stem)
    return _nm(p)

# %% ../nbs/01_tree.ipynb #cb05fc7e
def folder_link(p, text=None):
    "Return Solveit folder link"
    rel = p.resolve().relative_to(Path('/app/data'))
    return A(text or p.name, href=f"/?at={quote(str(rel))}", target='_blank')

def file_link(p, text=None):
    "Return Solveit file editor link"
    return A(text or p.name, href=f"/file_editor_?fp={quote(str(p.resolve()))}", target='_blank')

def solveit_link(p):
    "Return Solveit link for Path"
    if p.is_dir(): return folder_link(p)
    if p.suffix=='.ipynb': return dlink('/' + str(p.resolve().with_suffix('').relative_to(Path('/app/data'))), p.stem)
    return file_link(p)

